import{_ as e,o,c as l,a5 as a}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"模板中的动态导入","description":"是的，你可以在定义 tabPaneMap 时使用动态导入 (import())，这样做的好处包括 按需加载组件 和 优化首屏加载性能 。具体地说： 动态导入的写法 可以将 tabPaneMap 改为动态导入的方式，如下： const tabPaneMap \\\\{ real: ()。","frontmatter":{"title":"模板中的动态导入","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"是的，你可以在定义 tabPaneMap 时使用动态导入 (import())，这样做的好处包括 按需加载组件 和 优化首屏加载性能 。具体地说： 动态导入的写法 可以将 tabPaneMap 改为动态导入的方式，如下： const tabPaneMap \\\\{ real: ()。","sidebarWeight":8,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/动态导入/模板中的动态导入.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/模板中的动态导入.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/模板中的动态导入.md"}'),i={name:"posts/Vue系统教程/06-工程化、质量与性能/模板中的动态导入.md"};function s(r,t,n,p,u,g){return o(),l("div",null,[...t[0]||(t[0]=[a('<div><h1 id="模板中的动态导入" tabindex="-1">模板中的动态导入 <a class="header-anchor" href="#模板中的动态导入" aria-label="Permalink to &quot;模板中的动态导入&quot;">​</a></h1><blockquote><p>本节目标：理解“模板中的动态导入”的核心思路，并能把它用于实际开发或面试表达。 是的，你可以在定义 tabPaneMap 时使用动态导入 (import())，这样做的好处包括<strong>按需加载组件</strong>和<strong>优化首屏加载性能</strong>。具体地说： <strong>动态导入的写法</strong> 可以将 tabPaneMap 改为动态导入的方式，如下： const tabPaneMap = { real: () =&gt; import(&#39;./real.vue&#39;), mock: () =&gt; import(&#39;./mock.vue&#39;), archive: () =&gt; import(&#39;./archive.vue&#39;), outside: () =&gt; import(&#39;./outside.vue&#39;),} 在模板中，动态导入的组件会需要使用 defineAsyncComponent 来解析，例如： &lt;template&gt; &lt;MTabs v-model:activeKey=&quot;state.activeKey&quot; :tabs=&quot;tabs&quot; ... &gt; &lt;template #[key] :key=&quot;key&quot; v-for=&quot;{ key } in tabs&quot;&gt; &lt;Suspense&gt; &lt;component :is=&quot;resolveComponent(key)&quot; /&gt; &lt;template #fallback&gt; &lt;div&gt;加载中...&lt;/div&gt; &lt;/template&gt; &lt;/Suspense&gt; &lt;/template&gt; &lt;/MTabs&gt;&lt;/template&gt; &lt;script setup lang=&quot;ts&quot;&gt;import { reactive } from &#39;vue&#39;import { Suspense, defineAsyncComponent } from &#39;vue&#39; const tabPaneMap = { real: () =&gt; import(&#39;./real.vue&#39;), mock: () =&gt; import(&#39;./mock.vue&#39;), archive: () =&gt; import(&#39;./archive.vue&#39;), outside: () =&gt; import(&#39;./outside.vue&#39;),} const resolveComponent = (key: string) =&gt; defineAsyncComponent(tabPaneMap[key]) const tabs = [ { key: &#39;real&#39;, label: &#39;真实&#39; }, { key: &#39;mock&#39;, label: &#39;模拟&#39; }, { key: &#39;archive&#39;, label: &#39;已归档&#39; }, { key: &#39;outside&#39;, label: &#39;外部账户&#39; },] const state = reactive({ activeKey: &#39;real&#39;,})&lt;/script&gt;</p></blockquote><p><strong>动态导入的优点</strong></p><ol><li><strong>按需加载组件（Lazy Loading）：</strong><ul><li>使用动态导入时，组件的代码只有在被实际访问（如切换到对应的 tab）时才会加载。</li><li>如果某些组件内容复杂或依赖的代码量大，可以显著减小首屏加载的体积，提升用户体验。</li></ul></li><li><strong>优化性能：</strong><ul><li>组件的代码会被 Webpack 或 Vite 拆分成多个文件，形成独立的 JavaScript 异步模块。这种方式利用了浏览器的并行加载能力，提高资源加载效率。</li></ul></li><li><strong>减少首次加载时间：</strong><ul><li>如果组件较多且每个组件较大，通过动态导入，只加载当前使用的组件，避免所有组件一次性加载，减少初次渲染的阻塞。</li></ul></li><li><strong>代码分割（Code Splitting）：</strong><ul><li>动态导入能够自动触发代码分割，避免打包时把所有组件打到同一个 JavaScript 文件中。</li><li>每个动态导入的模块会生成独立的 chunk 文件，并且可以根据用户的实际使用按需加载。</li></ul></li><li><strong>用户体验：</strong><ul><li>对用户来说，首屏加载速度更快，切换 tab 时加载新组件可以显示加载状态（通过 Suspense 的 fallback 提供友好的提示）。</li></ul></li></ol><p><strong>动态导入的潜在注意点</strong></p><ol><li><strong>加载延迟：</strong><ul><li>动态导入需要发送额外的 HTTP 请求去加载相应的模块，所以初次加载某个组件时会有延迟。</li><li>解决方法是使用 Suspense 提供占位内容，如 “加载中...” 提示。</li></ul></li><li><strong>在开发环境中可能不直观：</strong><ul><li>在开发过程中，动态导入的模块可能会导致调试不直观，因为模块是在运行时加载的，而不是一开始就明确导入。</li></ul></li><li><strong>适用场景：</strong><ul><li>动态导入适合用于大型或不常用的模块。如果组件很小，动态导入的开销（如额外的 HTTP 请求）可能超过节省的成本。</li></ul></li></ol><p><strong>适用场景</strong> 动态导入非常适合以下情况：</p><ul><li>组件内容较多，且只会在特定条件下使用。</li><li>不同的 tab 对应的内容复杂，且有可能不会全部访问。</li><li>需要优化首屏性能，但允许在后台加载非关键内容。</li></ul><p>如果页面中 tab 的数量较少且组件较小，可以继续使用静态导入，这样可以避免不必要的加载延迟。动态导入更适用于<strong>较多、较大组件</strong>的场景。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6781de87-f0e8-8004-9798-59cb331ee95a" target="_blank" rel="noreferrer">https://chatgpt.com/c/6781de87-f0e8-8004-9798-59cb331ee95a</a>&gt;</p></div>',1)])])}const d=e(i,[["render",s]]);export{m as __pageData,d as default};
